import{c as a,Q as s,j as t,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Recursive Agent Harnesses","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.13643","title":"Recursive Agent Harnesses","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2606.13643,"authors":["Elias Lumer","Sahil Sen","Kevin Paul","Vamse Kumar Subbiah"],"pdf_path":"pdfs/2606.13643.pdf","published_date":"2026-06-11T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-11-recursive-agent-harnesses-2606-13643.md","filePath":"research/papers/2026-06-11-recursive-agent-harnesses-2606-13643.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-11-recursive-agent-harnesses-2606-13643.md"};function o(i,e,c,h,l,d){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="recursive-agent-harnesses" tabindex="-1">Recursive Agent Harnesses <a class="header-anchor" href="#recursive-agent-harnesses" aria-label="Permalink to &quot;Recursive Agent Harnesses&quot;">​</a></h1><p><strong>Authors</strong>: Elias Lumer, Sahil Sen, Kevin Paul, Vamse Kumar Subbiah <strong>Published</strong>: June 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.13643" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.13643</a><strong>arXiv ID</strong>: 2606.13643 <strong>Categories</strong>: Computation and Language (cs.CL) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.13643" target="_blank" rel="noreferrer">research/papers/pdfs/2606.13643.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The paper explores how recursion over model calls is an effective strategy for long-context reasoning, extending this concept to what they term Recursive Agent Harness (RAH). Their approach enables parent agents to generate and execute scripts that spawn multiple subagent harnesses in parallel, equipped with filesystem tools, code execution capabilities, and planning functions. The researchers conducted controlled evaluations on long-context reasoning tasks. Using GPT-5 as the baseline model, RAH improved performance from 71.75% to 81.36% on the Oolong-Synthetic benchmark (199 samples with context lengths reaching 4M tokens). When tested with Claude Sonnet 4.5, the same design architecture achieved 89.77% accuracy, demonstrating the effectiveness of the harness design independent of model strength.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>提出 Recursive Agent Harness (RAH)：parent agent 生成並執行腳本，動態 spawn 多個並行 subagent harness（各自配備檔案系統工具、程式碼執行、規劃能力），將長上下文推理遞迴分解。</li><li>在 Oolong-Synthetic benchmark（199 樣本、上下文長達 4M token）上，GPT-5 基準效能從 71.75% 提升至 81.36%；換成 Claude Sonnet 4.5 達 89.77%，顯示 harness 設計效益獨立於底層模型強弱。</li><li>核心論點：遞迴式 model call 分解是處理超長上下文推理的有效策略，勝過單一 agent 在巨大上下文窗口內硬撐。</li><li><strong>Workspace 關聯</strong>：與本 workspace 的 sub-agent 委派拓撲（<code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>） context 隔離／fan-out）在架構精神上高度一致——parent 調度 + 並行 sub-harness 執行，可作為未來評估「大型長任務是否該拆給多個 sub-agent 而非塞爆單一 context window」的量化參照（4M token 規模下遞迴分解優於單一長 context）。</li></ul>',8)])])}const p=a(n,[["render",o]]);export{u as __pageData,p as default};
